// Loop over all incoming items
for (const item of $input.all()) {
  const messageText = item.json.message?.text;

  if (messageText) {
    // Updated Regex: Looks for the exact 11-character YouTube ID
    const regExp = /(?:youtu\.be\/|v\/|u\/\w\/|embed\/|shorts\/|watch\?v=|\&v=)([a-zA-Z0-9_-]{11})/;\n    const match = messageText.match(regExp);

    if (match && match[1]) {
      item.json.videoId = match[1];
    } else {
      item.json.videoId = null;
    }
  } else {
    item.json.videoId = null;
  }
}
return $input.all();

parameters.text:
=Title: {{ $json.title }}

Transcript:
{{ $json.tracks[0].transcript.map(chunk => chunk.text).join(' ') }}

You are an expert technical writer. Distill this YouTube transcript into a summary. Extract the main topic, a short summary, 4-6 key highlights, prerequisites (or say 'None'), and a big takeaway. Do not use markdown, just provide the clean text as requested by the output schema.

parameters.jsonSchema:
{
  "type": "object",
  "properties": {
    "main_topic": {
      "type": "string",
      "description": "The main topic of the video in 5-7 words"
    },
    "summary": {
      "type": "string",
      "description": "A 2-3 sentence overview of the video"
    },
    "key_highlights": {
      "type": "array",
      "items": {
        "type": "string"
      },
      "description": "4-6 actionable bullet points from the video"
    },
    "prerequisites": {
      "type": "string",
      "description": "Any technical prerequisites to understand the video, or 'None! This video is beginner-friendly.'"
    },
    "takeaway": {
      "type": "string",
      "description": "A single, impactful concluding sentence"
    }
  },
  "required": ["main_topic", "summary", "key_highlights", "prerequisites", "takeaway"]
}

