for (const item of $input.all()) {
  // Safely extract the JSON output from the AI Agent
  const data = item.json.output;

  // Helper function to escape HTML characters so Telegram doesn't crash
  const escapeHtml = (unsafe) => {
      return unsafe
           .replace(/&/g, "&amp;")
           .replace(/</g, "&lt;")
           .replace(/>/g, "&gt;");
  };

  let htmlMessage = `<b>📌 ${escapeHtml(data.main_topic)}</b>\n\n`;
  htmlMessage += `<b>📖 Summary</b>\n${escapeHtml(data.summary)}\n\n`;

  htmlMessage += `<b>🔑 Key Highlights</b>\n`;
  data.key_highlights.forEach(point => {
      htmlMessage += `• ${escapeHtml(point)}\n`;
  });

  htmlMessage += `\n<b>🧠 Prerequisites</b>\n${escapeHtml(data.prerequisites)}\n\n`;
  htmlMessage += `<b>💡 The Big Takeaway</b>\n${escapeHtml(data.takeaway)}`;

  // Pass the safely constructed HTML string to the next node
  item.json.telegramMessage = htmlMessage;
}
return $input.all();
